struct RClass*
get_real_class(struct RClass* cl)
{
  if (!cl) {
    return NULL;
  }

  while (cl) {
    if (!(RCLASS_FLAGS(cl) & (RCLASS_FLAG_SINGLETON | RCLASS_FLAG_INCLUDED))) {
      return cl;
    }
    cl = RCLASS_SUPER(cl);
  }

  return NULL;
}

struct RClass*
get_real_class(struct RClass *cl) {
  if (!cl) {
    return NULL;
  }

  while (cl) {
    if (RCLASS_SINGLETON_P(cl)) {
      cl = RCLASS_SUPER(cl);
    } else if (RCLASS_INCLUDED_P(cl)) {
      cl = RCLASS_SUPER(cl);
    } else {
      return cl;
    }
  }

  return NULL;
}

struct RClass* get_real_class(struct RClass* cl) {
  if (cl == NULL) {
    return NULL;
  }

  while (1) {
    if (cl->ptr && RCLASS_SUPER(cl) == NULL) {
      // Reached the top of the class hierarchy
      break;
    }

    if (RCLASS_SUPER(cl) != NULL) {
      cl = RCLASS_SUPER(cl);
    } else {
      // No more classes in the hierarchy
      break;
    }
  }

  return cl;
}

struct RClass* get_real_class(struct RClass* cl) {
  if (cl == NULL) {
    return NULL;
  }

  while (1) {
    if (BUILTIN_TYPE(cl) == MRB_TT_CLASS || BUILTIN_TYPE(cl) == MRB_TT_MODULE) {
      return cl;
    }

    if (cl->c == NULL) {
      return NULL;
    }

    cl = cl->c;
  }
}

struct RClass* get_real_class(struct RClass* cl) {
  if (!cl) {
    return NULL;
  }

  while (cl) {
    if (!RCLASS_CLS(cl) && !RCLASS_IV_TBL(cl)) {
      return cl;
    }
    cl = RCLASS_SUPER(cl);
  }

  return NULL;
}
